import XCTest
@testable import JS8Core

/// Audio-level cross-checks: signals generated by the reference are decoded
/// by both decoders, and signals generated by the Swift modulator are decoded
/// by the reference decoder.
final class DecoderComparisonTests: XCTestCase {
    var ref: RefHarness!
    let dir = FileManager.default.temporaryDirectory.appendingPathComponent("js8tests", isDirectory: true)

    override func setUpWithError() throws {
        try XCTSkipUnless(RefHarness.isAvailable, "reference harness not built")
        ref = try RefHarness()
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
    }

    func readRaw(_ url: URL) -> [Float] {
        let data = try! Data(contentsOf: url)
        return data.withUnsafeBytes { raw in raw.bindMemory(to: Int16.self).map { Float($0) } }
    }

    func writeRaw(_ samples: [Float], _ url: URL) {
        let ints = samples.map { Int16(max(-32767, min(32767, $0.rounded()))) }
        let data = ints.withUnsafeBufferPointer { Data(buffer: $0) }
        try! data.write(to: url)
    }

    struct Line: Equatable {
        var frame: String
        var type: Int
        var snr: Int
        var dt: Float
        var freq: Float
    }

    func parse(_ lines: [String]) -> [Line] {
        lines.map { l in
            let f = l.split(separator: "\t", omittingEmptySubsequences: false).map(String.init)
            return Line(frame: f[0], type: Int(f[1])!, snr: Int(f[2])!, dt: Float(f[3])!, freq: Float(f[4])!)
        }
    }

    func swiftDecode(_ samples: [Float], _ submode: JS8Submode, nfqso: Int = 1500) -> [Line] {
        let dec = JS8ModeDecoder(submode: submode)
        var out: [Line] = []
        _ = samples.withUnsafeBufferPointer { buf in
            dec.decode(samples: buf, nfqso: nfqso) { d in
                out.append(Line(frame: d.frame, type: d.type, snr: d.snr, dt: d.dt, freq: d.frequency))
            }
        }
        return out
    }

    func testReferenceSignalsDecodeIdentically() {
        var g = SeededGenerator(seed: 11)
        var total = 0, refOK = 0, swiftOK = 0, snrDiffs: [Int] = []
        for submode in JS8Submode.allCases {
            for snr in [-10, -16, -20, -24] {
                for k in 0..<3 {
                    let frame = String((0..<12).map { _ in JS8Codec.alphabet[Int.random(in: 0..<64, using: &g)] })
                    let type = Int.random(in: 0..<8, using: &g)
                    let freq = 500 + Double(Int.random(in: 0..<2000, using: &g))
                    let url = dir.appendingPathComponent("ref_\(submode.rawValue)_\(snr)_\(k).raw")
                    XCTAssertEqual(ref.call(["GEN", url.path, "\(submode.rawValue)", "\(freq)", "\(type)", frame, "\(snr)", "\(k + 1)"]), "OK")
                    let refLines = parse(ref.callUntilEnd(["DECODE", url.path, "\(submode.rawValue)", "1500"]))
                    let swiftLines = swiftDecode(readRaw(url), submode)
                    total += 1
                    let r = refLines.first { $0.frame == frame && $0.type == type }
                    let s = swiftLines.first { $0.frame == frame && $0.type == type }
                    if r != nil { refOK += 1 }
                    if s != nil { swiftOK += 1 }
                    if let r, let s {
                        snrDiffs.append(abs(r.snr - s.snr))
                        XCTAssertEqual(r.freq, s.freq, accuracy: 0.6, "freq \(submode) \(snr)")
                        XCTAssertEqual(r.dt, s.dt, accuracy: 0.02, "dt \(submode) \(snr)")
                    }
                    if (r == nil) != (s == nil) {
                        print("MISMATCH \(submode) snr \(snr) ref=\(r != nil) swift=\(s != nil)")
                    }
                    // Never decode garbage.
                    XCTAssertTrue(swiftLines.allSatisfy { $0.frame == frame }, "false decode \(swiftLines)")
                }
            }
        }
        print("decodes: total=\(total) reference=\(refOK) swift=\(swiftOK) maxSNRdiff=\(snrDiffs.max() ?? -1)")
        XCTAssertGreaterThanOrEqual(swiftOK, refOK)
        XCTAssertLessThanOrEqual(snrDiffs.max() ?? 0, 1)
    }

    func testSwiftModulatedSignalsDecodeInReference() {
        var g = SeededGenerator(seed: 21)
        for submode in JS8Submode.allCases {
            for k in 0..<4 {
                let frame = String((0..<12).map { _ in JS8Codec.alphabet[Int.random(in: 0..<64, using: &g)] })
                let type = Int.random(in: 0..<8, using: &g)
                let freq = 400 + Double(Int.random(in: 0..<2200, using: &g))
                let tones = JS8Codec.encode(type: type, frame: frame, costas: submode.costas)!
                let wave = JS8Modulator.synthesize(tones: tones, frequency: freq, submode: submode, sampleRate: 12000, amplitude: 1)
                var samples = [Float](repeating: 0, count: submode.samplesPerPeriod)
                let start = submode.startDelayMS * 12
                var noise = SeededGenerator(seed: UInt64(k + 100))
                for i in samples.indices {
                    let s: Float = (i >= start && i - start < wave.count) ? wave[i - start] : 0
                    samples[i] = 1000 * s + 600 * gaussian(&noise)
                }
                let url = dir.appendingPathComponent("swift_\(submode.rawValue)_\(k).raw")
                writeRaw(samples, url)
                let refLines = parse(ref.callUntilEnd(["DECODE", url.path, "\(submode.rawValue)", "1500"]))
                XCTAssertTrue(refLines.contains { $0.frame == frame && $0.type == type },
                              "reference failed to decode Swift signal \(submode) \(frame) @ \(freq): \(refLines)")
                let swiftLines = swiftDecode(samples, submode)
                XCTAssertTrue(swiftLines.contains { $0.frame == frame && $0.type == type })
            }
        }
    }

    func testMultipleSignalsAndTiming() {
        let submode = JS8Submode.normal
        var samples = [Float](repeating: 0, count: submode.samplesPerPeriod)
        var noise = SeededGenerator(seed: 5)
        let frames = ["HELLOWORLD12", "KN4CRDTESTAB", "abcdefghijkl", "0123456789-+"]
        let freqs = [600.0, 1100.0, 1520.0, 2200.0]
        let offsets = [0.0, 0.3, -0.2, 0.8]
        for (i, f) in frames.enumerated() {
            let tones = JS8Codec.encode(type: i, frame: f, costas: submode.costas)!
            let wave = JS8Modulator.synthesize(tones: tones, frequency: freqs[i], submode: submode, sampleRate: 12000)
            let start = submode.startDelayMS * 12 + Int(offsets[i] * 12000)
            for (j, v) in wave.enumerated() where start + j >= 0 && start + j < samples.count {
                samples[start + j] += 300 * v
            }
        }
        for i in samples.indices { samples[i] += 500 * gaussian(&noise) }
        let start = Date()
        let lines = swiftDecode(samples, submode)
        print("multi-signal decode took \(Date().timeIntervalSince(start)) s: \(lines)")
        for (i, f) in frames.enumerated() {
            guard let l = lines.first(where: { $0.frame == f }) else {
                XCTFail("missing \(f)")
                continue
            }
            XCTAssertEqual(Double(l.freq), freqs[i], accuracy: 1.0)
            XCTAssertEqual(Double(l.dt), offsets[i], accuracy: 0.05)
        }
        let url = dir.appendingPathComponent("multi.raw")
        writeRaw(samples, url)
        let refLines = parse(ref.callUntilEnd(["DECODE", url.path, "0", "1500"]))
        XCTAssertEqual(Set(refLines.map(\.frame)), Set(lines.map(\.frame)))
    }
}

func gaussian(_ g: inout SeededGenerator) -> Float {
    let u1 = max(Double(g.next() >> 11) / Double(1 << 53), 1e-12)
    let u2 = Double(g.next() >> 11) / Double(1 << 53)
    return Float((-2 * log(u1)).squareRoot() * cos(2 * Double.pi * u2))
}
